import fs from 'fs';
const path = process.argv[2];
const lines = fs.readFileSync(path, 'utf8').split('\n').filter(Boolean);
const t = (s, n = 900) => (s || '').replace(/\s+/g, ' ').slice(0, n);
for (const l of lines) {
  let e; try { e = JSON.parse(l); } catch { continue; }
  const ts = (e.timestamp || '').slice(11, 19);
  const m = e.message;
  if (!m) {
    if (e.attachment) continue;
    continue;
  }
  const role = m.role;
  const content = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
  for (const c of content) {
    if (c.type === 'text') {
      if (!c.text || !c.text.trim()) continue;
      console.log(`[${ts}] ${role.toUpperCase()}: ${t(c.text, role === 'user' ? 3000 : 1200)}`);
    } else if (c.type === 'tool_use') {
      const inp = JSON.stringify(c.input);
      console.log(`[${ts}]   tool ${c.name}: ${t(inp, 260)}`);
    } else if (c.type === 'tool_result') {
      const s = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      if (c.is_error) console.log(`[${ts}]   RESULT-ERR: ${t(s, 300)}`);
    }
  }
}

